
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_wb97x_v_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_wb97x_v", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.515646055846180e+00, -3.446677042880244e+00, -3.350111936713863e+00, -3.216512186622615e+00, -3.034832922898016e+00, -2.793857723645236e+00, -2.485601490426020e+00, -2.111608398937961e+00, -1.691638518387250e+00, -1.263383807753329e+00, -8.235470627612825e-01, -4.913695609396159e-01, -4.132460083519023e-01, -3.190325416920806e-01, -1.992491485146138e-01, -8.949220768818587e-02, -2.139851824356474e-02, -2.169473210648075e-03, -5.487472373955300e-04, -9.375319190570900e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


